"  const handleVerifyPasscode = () => {
    if (!passcodeValue) {
      setPasscodeError('Please enter a passcode');
      return;
    }
    const matchingStaff = staffUsers.find(s => s.pos_pin === passcodeValue);
    if (!matchingStaff) {
      setPasscodeError('Invalid Passcode!');
      return;
    }

    let perms = {};
    if (matchingStaff.staff_permissions) {
      if (typeof matchingStaff.staff_permissions === 'string') {
        try {
          perms = JSON.parse(matchingStaff.staff_permissions);
        } catch (e) {
          perms = {};
        }
      } else {
        perms = matchingStaff.staff_permissions;
      }
    }

    const permissionKey = passcodeAction?.permissionKey;
    const hasPermission = checkStaffBillingPermission(perms, orderType, permissionKey);

    if (hasPermission) {
      toast.success(`Authorized by ${matchingStaff.name}`);
      setIsPasscodeModalOpen(false);
      if (passcodeAction?.onApproved) {
        passcodeAction.onApproved();
      }
    } else {
      setPasscodeError(`${matchingStaff.name} does not have this permission!`);
    }
  };"
